def parse_percent(text: str) -> tuple[str, int]:
    """Turn user input such as "alice=50" into ("alice", 50)."""
    name, separator, number = text.partition("=")
    name, number = name.strip(), number.strip()
    if not separator or not name or not (number.isascii() and number.isdigit()):
        raise MoneyError(f"expected NAME=PERCENT, for example alice=50: {text!r}")
    percent = int(number)
    if not 1 <= percent <= 100:
        raise MoneyError(f"percent must be a whole number from 1 to 100: {text!r}")
    return name, percent


